CREATE TABLE wb_provider_configs(id text PRIMARY KEY,name text NOT NULL,protocol text NOT NULL,base_url text NOT NULL,api_key_env text NOT NULL DEFAULT '',headers jsonb NOT NULL DEFAULT '{}',model text NOT NULL,task_types jsonb NOT NULL DEFAULT '[]',enabled boolean NOT NULL DEFAULT true,is_default boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wb_prompt_templates(id text PRIMARY KEY,task_type text NOT NULL,name text NOT NULL,version integer NOT NULL,prompt text NOT NULL,response_schema jsonb,rules jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(name,version));
CREATE TABLE wb_agent_definitions(id text PRIMARY KEY,name text NOT NULL,task_type text NOT NULL,prompt_template_id text NOT NULL DEFAULT '',tools jsonb NOT NULL DEFAULT '[]',max_output_tokens integer NOT NULL DEFAULT 3000,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wb_workflows(id text PRIMARY KEY,name text NOT NULL,version integer NOT NULL,definition jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(name,version));
CREATE TABLE wb_productions(id text PRIMARY KEY,project_id text NOT NULL REFERENCES wb_projects(id) ON DELETE CASCADE,workflow_snapshot jsonb NOT NULL,chapter_ids jsonb NOT NULL,max_cost double precision,currency text NOT NULL DEFAULT '',manual_gates boolean NOT NULL DEFAULT true,status text NOT NULL,error text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz);
CREATE TABLE wb_production_steps(id text PRIMARY KEY,production_id text NOT NULL REFERENCES wb_productions(id) ON DELETE CASCADE,chapter_id text NOT NULL REFERENCES wb_chapters(id),step_id text NOT NULL,sort_order integer NOT NULL,status text NOT NULL,task_run_id text NOT NULL DEFAULT '',approved boolean NOT NULL DEFAULT false,error text NOT NULL DEFAULT '',UNIQUE(production_id,chapter_id,step_id));
CREATE TABLE wb_run_cache(cache_key text PRIMARY KEY,project_id text NOT NULL REFERENCES wb_projects(id) ON DELETE CASCADE,chapter_id text NOT NULL REFERENCES wb_chapters(id),revision_id text NOT NULL,epoch bigint NOT NULL,input_hash text NOT NULL,output jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wb_embedding_configs(id text PRIMARY KEY,name text NOT NULL,base_url text NOT NULL,api_key_env text NOT NULL DEFAULT '',model text NOT NULL,dimension integer NOT NULL,kind text NOT NULL CHECK(kind IN ('embedding','rerank')),enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wb_embeddings(chunk_id text NOT NULL REFERENCES wb_chunks(id) ON DELETE CASCADE,config_id text NOT NULL REFERENCES wb_embedding_configs(id) ON DELETE CASCADE,model text NOT NULL,dimension integer NOT NULL,source_hash text NOT NULL,vector jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(chunk_id,config_id));
CREATE TABLE wb_context_summaries(id text PRIMARY KEY,project_id text NOT NULL REFERENCES wb_projects(id) ON DELETE CASCADE,epoch bigint NOT NULL,summary text NOT NULL,sources jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
